package android.bluetooth; public class BluetoothDevice {public static final int BOND_BONDED=12;public int bondState=BOND_BONDED;public int getBondState(){return bondState;}private final String name,address;public BluetoothDevice(String name,String address){this.name=name;this.address=address;}public String getName(){return name;}public String getAddress(){return address;}public boolean equals(Object other){return other instanceof BluetoothDevice&&address.equals(((BluetoothDevice)other).address);}public int hashCode(){return address.hashCode();}}
